#include "quit_bridge_shim.h"
#include <cstdio>
namespace {int checks=0;std::vector<QPointer<MemoryDock>> inventory;}
#define CHECK(x) do{++checks;if(!(x)){std::fprintf(stderr,"failed line %d: %s\n",__LINE__,#x);std::abort();}}while(0)
QList<QWidget*>QApplication::allWidgets(){QList<QWidget*>out;for(auto&d:inventory)if(d)out.push_back(d);return out;}
using Status=ks::ui::LeaveEntryStatus;
void reset(){inventory.clear();qApp->setProperty("ksword_memory_quit_guard_active",false);QCoreApplication::processEvents();}
int main(int argc,char**argv){QCoreApplication app(argc,argv);
 {reset();MainWindow root;CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Completed);CHECK(root.finalCloses==0);root.close();CHECK(root.finalCloses==1);}
 {reset();MainWindow root;MemoryDock a,b,c;inventory={&a,&b,&c};b.entry=Status::Pending;CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Pending);CHECK(a.preparations==1&&b.preparations==1&&c.preparations==0);CHECK(a.releases==0&&b.releases==0);CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Pending);CHECK(a.preparations==1&&b.preparations==1);b.completion(true);QCoreApplication::processEvents();CHECK(root.finalCloses==1);CHECK(a.preparations==1&&b.preparations==1&&c.preparations==1);CHECK(a.releases==1&&b.releases==1&&c.releases==1);b.completion(true);QCoreApplication::processEvents();CHECK(root.finalCloses==1);}
 {reset();MainWindow root;MemoryDock a,b;inventory={&a,&b};b.entry=Status::Pending;CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Pending);b.completion(false);CHECK(a.cancels==1&&b.cancels==1);CHECK(root.m_shutdownRestart.cancels==1);CHECK(!qApp->property("ksword_memory_quit_guard_active").toBool());b.completion(true);QCoreApplication::processEvents();CHECK(root.finalCloses==0&&a.releases==0);}
 {reset();MainWindow root;MemoryDock a,b;inventory={&a,&b};b.entry=Status::Pending;CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Pending);a.current=false;b.completion(true);QCoreApplication::processEvents();CHECK(root.finalCloses==0&&a.releases==0&&a.cancels==1);}
 {reset();MainWindow root;MemoryDock a;auto b=std::make_unique<MemoryDock>();inventory={&a,b.get()};b->entry=Status::Pending;CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Pending);auto old=b->completion;b.reset();CHECK(a.cancels==1);CHECK(!qApp->property("ksword_memory_quit_guard_active").toBool());old(true);QCoreApplication::processEvents();CHECK(root.finalCloses==0);}
 {reset();MemoryDock a,b;inventory={&a,&b};b.entry=Status::Pending;auto root=std::make_unique<MainWindow>();CHECK(root->prepareMemoryWorkbenchesForShutdown()==Status::Pending);auto old=b.completion;root.reset();CHECK(a.cancels==1&&b.cancels==1);CHECK(!qApp->property("ksword_memory_quit_guard_active").toBool());old(true);}
 {reset();MainWindow root;MemoryDock a,b;inventory={&a};a.duringPrepare=[&]{inventory.push_back(&b);};CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Completed);CHECK(a.preparations==1&&b.preparations==1);}
 {reset();MainWindow root;MemoryDock a,b;inventory={&a};a.duringRelease=[&]{inventory.push_back(&b);};CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Rejected);CHECK(a.cancels==1&&b.cancels==1);CHECK(root.finalCloses==0);}
 {reset();MainWindow root;MemoryDock a;inventory={&a};a.entry=Status::Busy;CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Rejected);CHECK(a.preparations==1&&a.releases==0&&root.m_shutdownRestart.cancels==1);}
 {reset();MainWindow root;MemoryDock a;inventory={&a};a.duringPrepare=[&]{CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Pending);};CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Completed);CHECK(a.preparations==1);}
 {reset();MainWindow root;MemoryDock a;inventory={&a};a.entry=Status::Pending;int beats=0;QTimer heartbeat;QObject::connect(&heartbeat,&QTimer::timeout,&app,[&]{++beats;});heartbeat.start(1);CHECK(root.prepareMemoryWorkbenchesForShutdown()==Status::Pending);QTimer::singleShot(40,&app,[&]{a.completion(true);});QTimer::singleShot(65,&app,&QCoreApplication::quit);app.exec();CHECK(beats>5&&root.finalCloses==1&&a.preparations==1);}
 {reset();MemoryDock dock;ProcessDetailWindow window;window.m_embeddedMemoryDock=&dock;dock.entry=Status::Pending;QCloseEvent event;window.closeEvent(&event);CHECK(event.ignored&&window.baseCloses==0);dock.completion(true);QCoreApplication::processEvents();CHECK(window.baseCloses==1&&dock.preparations==1);dock.completion(true);QCoreApplication::processEvents();CHECK(window.baseCloses==1);}
 {reset();MemoryDock dock;ProcessDetailWindow window;window.m_embeddedMemoryDock=&dock;dock.entry=Status::Pending;QCloseEvent event;window.closeEvent(&event);dock.completion(false);QCoreApplication::processEvents();CHECK(window.baseCloses==0&&!window.property("ksword_memory_detail_close_guard_active").toBool());}
 {reset();auto dock=std::make_unique<MemoryDock>();ProcessDetailWindow window;window.m_embeddedMemoryDock=dock.get();dock->entry=Status::Pending;QCloseEvent event;window.closeEvent(&event);dock.reset();CHECK(window.m_embeddedMemoryDock==nullptr&&!window.property("ksword_memory_detail_close_guard_active").toBool());}
 {reset();MemoryDock dock;auto window=std::make_unique<ProcessDetailWindow>();window->m_embeddedMemoryDock=&dock;dock.entry=Status::Pending;QCloseEvent event;window->closeEvent(&event);window.reset();dock.completion(true);QCoreApplication::processEvents();CHECK(dock.preparations==1);}
 std::printf("quit bridge checks=%d\n",checks);return 0;}
